const count = (arr, key) => { const o = {}; arr.forEach(r => { const k = String(r[key] || '').trim() || '(blank)'; o[k] = (o[k] || 0) + 1; }); return Object.entries(o).sort((a, b) => b[1] - a[1]).slice(0, 6); };
const noReply = customers.filter(r => !String(r.replied_at || '').trim() && !String(r.outcome || '').trim());
const stats = { week_of: since.toFormat('LLL d') + ' to ' + now.toFormat('LLL d'), customers: customers.length, unclear: unclear.length, pitches: pitches.length, spam: spam.length, total: leads.length + pitches.length + spam.length,
  emergencies: customers.filter(r => r.urgency === 'emergency').length, repeats: customers.filter(r => r.status === 'repeat').length, services: count(customers, 'service'), pages: count(customers, 'page'), phone_types: count(customers, 'phone_type'), pitch_kinds: count(pitches, 'category'), no_reply: noReply.length };
const sheet = 'https://docs.google.com/spreadsheets/d/' + cfg.spreadsheet_id;
const li = arr => '<ul>' + arr.map(x => '<li>' + x + '</li>').join('') + '</ul>';
const html = [
  '<h2>' + esc(cfg.business_name) + ' website leads, ' + esc(stats.week_of) + '</h2>',
  '<p><b>' + stats.total + ' submissions:</b> ' + stats.customers + ' real customer' + (stats.customers === 1 ? '' : 's') + ', ' + stats.unclear + ' to check, ' + stats.pitches + ' vendor pitches or job seekers, ' + stats.spam + ' spam.' + (stats.emergencies ? ' ' + stats.emergencies + ' marked urgent.' : '') + (stats.repeats ? ' ' + stats.repeats + ' wrote in more than once.' : '') + '</p>',
  stats.services.length ? '<p><b>What customers asked for</b></p>' + li(stats.services.map(([k, n]) => esc(k) + ': ' + n)) : '',
  stats.pages.length && !(stats.pages.length === 1 && stats.pages[0][0] === '(blank)') ? '<p><b>Where they came from</b></p>' + li(stats.pages.map(([k, n]) => esc(k) + ': ' + n)) : '',
  stats.phone_types.length ? '<p>Phone types: ' + esc(stats.phone_types.map(([k, n]) => k + ' ' + n).join(', ')) + '.</p>' : '',
  noReply.length ? '<p><b>' + noReply.length + ' customer' + (noReply.length === 1 ? '' : 's') + ' with no reply logged</b></p>' + li(noReply.map(r => esc((r.name || 'no name') + ', ' + (r.service || 'request') + ', ' + (r.phone || r.email || '')) + ' (' + esc(DateTime.fromISO(String(r.received_at)).setZone(cfg.timezone).toFormat('ccc')) + ')')) : '<p>Every customer this week has a reply or an outcome logged.</p>',
  stats.pitch_kinds.length ? '<p>Pitches: ' + esc(stats.pitch_kinds.map(([k, n]) => k.replace(/_/g, ' ') + ' ' + n).join(', ')) + '. Nobody was told about these.</p>' : '',
  '<p><a href="' + esc(sheet) + '">Spreadsheet</a>. Fill in replied_at and outcome on the Leads tab so next week\'s list is right.</p>',
].filter(Boolean).join('\n');
const subject = '[Leads] ' + stats.customers + ' real, ' + stats.pitches + ' pitches, ' + stats.spam + ' spam: week of ' + stats.week_of;
return [{ json: { stats, subject, html, to: cfg.owner_email } }];

// Example Services rows. Replace them with your own; the sorter uses them to tell a customer from a pitch.
