  { topic: 'what we do', detail: 'Residential plumbing: water heaters, drain cleaning, leak repair, repiping, gas lines, fixture installs.' },
  { topic: 'what we do not do', detail: 'Commercial work, septic, wells, new construction, HVAC.' },
  { topic: 'service area', detail: 'Cobb, Cherokee and north Fulton counties in Georgia. Zips starting 300 and 301. Not inside the Perimeter.' },
  { topic: 'how customers usually write', detail: 'Short, specific, often in a hurry: a leak, no hot water, a slow drain, a quote for a replacement. They give a street or a town.' },
  { topic: 'what pitches look like', detail: 'Offers of SEO, Google ranking, lead generation, web design, financing, software, staffing, "I noticed your website". Often polished, no address, no job.' },
].map(json => ({ json }));

const s = $('Create the spreadsheet').first().json;
return [{ json: {
  spreadsheet_id: s.spreadsheetId,
  spreadsheet_url: s.spreadsheetUrl || ('https://docs.google.com/spreadsheets/d/' + s.spreadsheetId),
  next_step: 'Paste spreadsheet_id into Your settings with your email, rewrite the Services tab for your business, then point your website form at the Form posts here URL (or use the built-in form) and publish.',
} }];

// The form's own copy of Read your settings. n8n does not let a form reach the page webhooks'
// replies, so the form gets its own way in. It reads Your settings directly; nothing to fill in here.
// Checks Your settings and works out what started this run: a form submission (webhook or the
// built-in form), the Monday summary, or the one-time spreadsheet setup.
const s = Object.fromEntries((($('Your settings').params.assignments || {}).assignments || []).map(a => [a.name, a.value]));
const ran = name => { try { return $(name).isExecuted; } catch (e) { return false; } };
const esc = v => String(v === undefined || v === null ? '' : v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const num = (v, d) => { if (v === '' || v === null || v === undefined) return d; const n = Number(String(v).replace(/[$,\s]/g, '')); return isNaN(n) ? d : n; };
const isEmail = v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v || '').trim());
const e164 = v => { const d = String(v || '').replace(/\D/g, ''); if (!d) return ''; if (d.length === 10) return '+1' + d; if (d.length === 11 && d[0] === '1') return '+' + d; return d.length >= 8 && d.length <= 15 ? '+' + d : ''; };
const list = v => (Array.isArray(v) ? v : []).map(x => String(x || '').trim()).filter(Boolean);
const links = t => (String(t || '').match(/https?:\/\/|www\./gi) || []).length;
const DISPOSABLE = ['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'yopmail.com', 'sharklasers.com', 'trashmail.com', 'getnada.com', 'dispostable.com', 'maildrop.cc'];
const mode = ran('Create my spreadsheet') ? 'setup' : (ran('Form posts here') || ran('Built-in form')) ? 'lead' : 'weekly';
const timezone = String(s.timezone || 'America/New_York').trim();
if (!DateTime.now().setZone(timezone).isValid) throw new Error('Your settings: "' + timezone + '" is not a time zone n8n knows. Use a name like America/New_York.');
const cfg = {
  business_name: String(s.business_name || 'Your Business').trim(),
  owner_email: String(s.owner_email || '').trim(),
  owner_cell: String(s.owner_cell || '').trim(),
  twilio_number: String(s.twilio_number || '').trim(),
  spreadsheet_id: String(s.spreadsheet_id || '').trim(),
  timezone,
  auto_reply: String(s.auto_reply).toLowerCase() !== 'false',
  check_phones: String(s.check_phones).toLowerCase() !== 'false',
  honeypot_field: String(s.honeypot_field || 'website').trim(),
  min_seconds: Math.max(0, num(s.min_seconds, 3)),
  repeat_days: Math.max(1, num(s.repeat_days, 7)),
};
cfg.text_alerts = /^\+\d{8,15}$/.test(cfg.owner_cell) && /^\+\d{8,15}$/.test(cfg.twilio_number);
if (mode !== 'setup') {
  const missing = [];
  if (!isEmail(cfg.owner_email)) missing.push('owner_email (where real leads and the Monday summary go)');
  if (!cfg.spreadsheet_id) missing.push('spreadsheet_id (run "Create my spreadsheet" once, then paste the ID it gives you)');
  if (missing.length) throw new Error('Your settings: fill in ' + missing.join('; ') + '.');
}
return [{ json: { mode, cfg } }];
